    fun describe(code: Int): WhatsminerErrorDetail {
        exact[code]?.let { return WhatsminerErrorDetail(code, it.title, it.solution) }

        val codeStr = code.toString()
        for (t in templates) {
            if (t.pattern.length == codeStr.length && matchesPattern(t.pattern, codeStr)) {
                return WhatsminerErrorDetail(
                    code,
                    substitute(t.pattern, t.title, codeStr),
                    substitute(t.pattern, t.solution, codeStr)
                )
            }
        }

        return WhatsminerErrorDetail(code, fallbackTitle(code), fallbackSolution(code))
    }

    /** خطاهای فعال منبع تغذیه را از روی یک مقدار بیت‌ماسک (hex) استخراج می‌کند؛ چند خطا می‌توانند هم‌زمان برگردند */
    fun describePsuFlags(bitmask: Int): List<WhatsminerErrorDetail> {
        if (bitmask == 0) return emptyList()
        val result = mutableListOf<WhatsminerErrorDetail>()
        for (bit in 0 until 16) {
            val flag = 1 shl bit
            if (bitmask and flag != 0) {
                psuFlags[flag]?.let { result.add(WhatsminerErrorDetail(flag, it.title, it.solution)) }
            }
        }
        return result
    }

    private fun matchesPattern(pattern: String, codeStr: String): Boolean {
        for (i in pattern.indices) {
            val p = pattern[i]
            if (p != 'X' && p != 'B' && p != codeStr[i]) return false
        }
        return true
    }

    // رقم(های) واقعیِ متناظر با ران X یا B در الگو را استخراج کرده و در متن جایگزین می‌کند
    // (مثلا الگوی "52XBBB" با کد "521234" یعنی X=1 و BBB=234؛ در متن SMX->SM1 و BBB->234 می‌شود)
    private fun substitute(pattern: String, text: String, codeStr: String): String {
        var result = text
        findRun(pattern, 'X')?.let { (start, len) ->
            result = result.replace("X", codeStr.substring(start, start + len))
        }
        findRun(pattern, 'B')?.let { (start, len) ->
            result = result.replace("B".repeat(len), codeStr.substring(start, start + len))
        }
        return result
    }

    private fun findRun(pattern: String, ch: Char): Pair<Int, Int>? {
        val start = pattern.indexOf(ch)
        if (start == -1) return null
        var end = start
        while (end < pattern.length && pattern[end] == ch) end++
        return start to (end - start)
    }

    // برای کدهایی که نه در جدول دقیق و نه در الگوها پیدا شدند: بر اساس بازهٔ عددی یک توضیح کلی برمی‌گردانیم
    private fun fallbackTitle(code: Int): String = when (code) {
        in 100..199 -> "خطای فن (کد $code)"
        in 200..299 -> "خطای منبع تغذیه / پاور (کد $code)"
        in 300..399 -> "خطای سنسور دمای هش‌برد (کد $code)"
        in 400..499 -> "خطای حافظه یا تنظیمات هش‌برد (کد $code)"
        in 500..599 -> "خطای اتصال یا چیپ هش‌برد (کد $code)"
        in 600..699 -> "خطای دمای محیط (کد $code)"
        in 700..799 -> "خطای برد کنترل (کد $code)"
        in 800..899 -> "خطای فریمور (کد $code)"
        in 2000..2999 -> "خطای شبکه یا استخر ماینینگ (کد $code)"
        in 5000..5999 -> "خطای فرکانس هش‌برد (کد $code)"
        in 8000..8999 -> "ناسازگاری نسخهٔ فریمور (کد $code)"
        in 90000..99999 -> "خروج غیرعادی یکی از فرایندهای دستگاه (کد $code)"
        else -> "کد خطای ناشناخته ($code)"
    }

    private fun fallbackSolution(code: Int): String = when (code) {
        in 100..199 -> "اتصال و سلامت فن‌ها را بررسی کنید؛ در صورت نیاز فن یا پاور را تعویض کنید"
        in 200..299 -> "شرایط برق ورودی (ولتاژ/جریان) و اتصال پاور را بررسی کنید؛ در صورت تکرار پاور را تعویض کنید"
        in 300..399 -> "اتصال هش‌برد و پیچ‌های برد کنترل را بررسی کنید"
        in 400..499 -> "اتصال برد رابط را بررسی کنید؛ در صورت ادامه با تکنسین تماس بگیرید"
        in 500..599 -> "اتصال هش‌برد، برد رابط و کانکتورها را بررسی و در صورت نیاز تمیز کنید"
        in 600..699 -> "دمای محیط اتاق ماینینگ را کاهش دهید و تهویه را بهبود ببخشید"
        in 700..799 -> "فریمور را به آخرین نسخه به‌روزرسانی کرده و پیچ‌های برد کنترل را بررسی کنید"
        in 800..899 -> "فریمور دستگاه را دوباره نصب یا به‌روزرسانی کنید"
        in 2000..2999 -> "اتصال شبکه و تنظیمات استخر (Pool) را بررسی کنید"
        in 5000..5999 -> "دستگاه را ری‌استارت کنید؛ در صورت تکرار با پشتیبانی تماس بگیرید"
        in 8000..8999 -> "نسخهٔ صحیح فریمور متناسب با مدل دستگاه را نصب کنید"
        in 90000..99999 -> "دستگاه را ری‌استارت کنید؛ در صورت تکرار فریمور را به‌روزرسانی کنید"
        else -> "برای بررسی دقیق‌تر با پشتیبانی یا تکنسین تماس بگیرید"
    }
